  }
  {
    SELECT DISTINCT ?investorId ?sector
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:investorId ?investorId .
      OPTIONAL { ?holding wm:sector ?sectorRaw . }
      OPTIONAL { ?holding wm:hasSector ?sectorNode . ?sectorNode rdfs:label ?sectorLabel . }
      BIND(COALESCE(STR(?sectorRaw), ?sectorLabel, "NULL") AS ?sector)
    }
  }
}
GROUP BY ?sector

