PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?categoryLabel ?totalHoldingGain ?avgGoalShortfall WHERE {
  {
    SELECT ?cat (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain) WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?inv ;
               wm:currentValue ?cv ;
               wm:cost ?cost .
      ?inv a wm:Investor ;
           wm:hasCategory ?cat .
      BIND( (xsd:decimal(?cv) - xsd:decimal(?cost)) AS ?gain )
    }
    GROUP BY ?cat
  }
  {
    SELECT ?cat (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:shortfall ?shortfall .
      ?inv a wm:Investor ;
           wm:hasCategory ?cat .
    }
    GROUP BY ?cat
  }
  BIND(?cat AS ?category)
  OPTIONAL { ?cat rdfs:label ?categoryLabel . }
}
ORDER BY ?categoryLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?avgGoalProgress) AS ?avg_goal_progress)
       (AVG(?avgRiskScore) AS ?avg_risk_score)
       (SUM(?totalHoldingValue) AS ?total_holding_value)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:riskTolerance ?riskToleranceRaw . }
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?riskTolerance)

  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?invGoal wm:investorId ?investorId ;
               wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
    WHERE {
      ?invHealth wm:investorId ?investorId ;
                 wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?invHold wm:investorId ?investorId ;
               wm:hasHolding ?holding .
      ?holding wm:currentValue ?holdingValue .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

