SELECT ?riskTolerance (SUM(?holdingValue) AS ?total_holding_value) (SUM(?sectorAllocValue) AS ?total_sector_allocation_investment)
WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?rtRaw . }
  BIND(COALESCE(STR(?rtRaw), "NULL") AS ?riskTolerance)

  {
    SELECT ?investorId (SUM(xsd:decimal(?cv)) AS ?holdingValue)
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?invH .
      ?invH wm:investorId ?investorId .
      ?holding wm:currentValue ?cv .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?ti)) AS ?sectorAllocValue)
    WHERE {
      ?alloc a wm:SectorAllocation .
      ?alloc wm:allocationOfInvestor ?invA .
      ?invA wm:investorId ?investorId .
      ?alloc wm:totalInvestment ?ti .
    }
    GROUP BY ?investorId
  }

  ?investor wm:investorId ?investorId .
}
