PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cash_source (SUM(?scenarioCountPerInvestor) AS ?scenario_count)
WHERE {
  # Aggregate scenario counts per investor
  {
    SELECT ?investorId (COUNT(?sr) AS ?scenarioCountPerInvestor)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  # Get distinct cash sources per investor
  {
    SELECT DISTINCT ?investorId ?cash_source
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId .
      OPTIONAL { ?cf wm:source ?src . }
      BIND(COALESCE(STR(?src), "NULL") AS ?cash_source)
    }
  }
}
GROUP BY ?cash_source

