PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (SUM(?invCount) AS ?investor_count) (SUM(?holdCount) AS ?holding_count)
WHERE {
  {
    SELECT ?category (COUNT(?inv) AS ?invCount) (0 AS ?holdCount)
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL { ?inv wm:category ?cat . }
      BIND(COALESCE(STR(?cat), "NULL") AS ?category)
    }
    GROUP BY ?category
  }
  UNION
  {
    SELECT ?category (0 AS ?invCount) (COUNT(?hold) AS ?holdCount)
    WHERE {
      ?hold a wm:PortfolioHolding .
      OPTIONAL { ?hold wm:category ?cat . }
      BIND(COALESCE(STR(?cat), "NULL") AS ?category)
    }
    GROUP BY ?category
  }
}
GROUP BY ?category

