PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(COALESCE(?totalHoldingGain, 0)) AS ?total_holding_gain)
       (SUM(COALESCE(?totalCashFlow, 0)) AS ?net_cash_flow)
       (AVG(?avgProgressPct) AS ?avg_progress_pct)
       (AVG(?avgRiskScore) AS ?avg_risk_score)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .

  OPTIONAL { ?investor wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain) WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?holding wm:currentValue ?currVal .
      ?holding wm:cost ?costVal .
      BIND((xsd:decimal(?currVal) - xsd:decimal(?costVal)) AS ?gain)
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?totalCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?cf wm:amount ?amt .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?prog)) AS ?avgProgressPct) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?goal wm:progressPct ?prog .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?risk)) AS ?avgRiskScore) WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?risk .
    } GROUP BY ?investorId
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category ?holding_sector (COUNT(?holding) AS ?holding_count)
WHERE {
  ?holding rdf:type wm:PortfolioHolding .
  ?holding wm:heldByInvestor ?investor .
  ?holding wm:holdingId ?holdingId .

  OPTIONAL {
    ?investor wm:hasCategory ?catNode .
    OPTIONAL { ?catNode rdfs:label ?catLabel . }
  }
  BIND(COALESCE(STR(?catLabel), "NULL") AS ?profile_category) .

  OPTIONAL {
    ?holding wm:hasSector ?sectorNode .
    OPTIONAL { ?sectorNode rdfs:label ?sectorLabel . }
  }
  BIND(COALESCE(STR(?sectorLabel), "NULL") AS ?holding_sector) .
}
GROUP BY ?profile_category ?holding_sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?goalContext (COUNT(?investor) AS ?investor_count)
WHERE {
  ?investor rdf:type wm:Investor .
  FILTER EXISTS { ?investor wm:hasHolding ?holding . }
  FILTER EXISTS { ?investor wm:hasSectorAllocation ?allocation . }
  FILTER EXISTS { ?investor wm:hasCashFlow ?cashflow . }

  OPTIONAL { ?investor wm:riskTolerance ?rtRaw . }
  BIND(COALESCE(STR(?rtRaw), "NULL") AS ?riskTolerance)

  OPTIONAL { ?investor wm:investmentGoal ?igRaw . }
  BIND(COALESCE(STR(?igRaw), "NULL") AS ?goalContext)
}
GROUP BY ?riskTolerance ?goalContext

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investment_type
       (AVG(?riskAvg) AS ?avg_risk_score)
       (AVG(?divAvg) AS ?avg_diversification_score)
       (AVG(?liqAvg) AS ?avg_liquidity_score)
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?riskScore)) AS ?riskAvg)
           (AVG(xsd:decimal(?divScore)) AS ?divAvg)
           (AVG(xsd:decimal(?liqScore)) AS ?liqAvg)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:investorId ?investorId ;
              wm:riskScore ?riskScore ;
              wm:diversificationScore ?divScore ;
              wm:liquidityScore ?liqScore .
    }
    GROUP BY ?investorId
  }
  {
    SELECT DISTINCT ?investorId ?investment_type
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:hasInvestmentType ?invTypeIRI .
      ?invTypeIRI rdfs:label ?investment_type .
    }
  }
}
GROUP BY ?investment_type

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
  OPTIONAL { ?inv wm:hasRiskTolerance ?risk . }
  OPTIONAL { ?inv wm:hasInvestmentGoal ?goal . }
  OPTIONAL { ?inv wm:hasSegment ?seg . }
  OPTIONAL { ?inv wm:hasCategory ?cat . }
  FILTER (
    !bound(?risk) ||
    !bound(?goal) ||
    !bound(?seg) ||
    !bound(?cat) ||
    NOT EXISTS {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?inv ;
               wm:hasCategory ?cat .
    }
  )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goal_context (AVG(xsd:decimal(?progressPct)) AS ?average_progress)
WHERE {
  ?goal rdf:type wm:InvestmentGoal ;
        wm:investmentGoal ?goal_context ;
        wm:progressPct ?progressPct ;
        wm:belongsToInvestor ?inv .
  ?inv rdf:type wm:Investor ;
       wm:riskTolerance ?riskTolerance .
  FILTER(LCASE(STR(?riskTolerance)) = "aggressive")
}
GROUP BY ?goal_context
ORDER BY DESC(?average_progress) ?goal_context
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance
       (AVG(xsd:decimal(?avgSharpeRatio)) AS ?avg_sharpe_ratio)
       (AVG(xsd:decimal(?avgVolatilityPct)) AS ?avg_volatility_pct)
WHERE {
  ?goal a wm:InvestmentGoal ;
        wm:goalId ?goalId ;
        wm:avgSharpeRatio ?avgSharpeRatio ;
        wm:avgVolatilityPct ?avgVolatilityPct ;
        wm:belongsToInvestor ?investor .
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTolRaw . }
  BIND(COALESCE(STR(?riskTolRaw), "NULL") AS ?risk_tolerance)
}
GROUP BY ?risk_tolerance
